const SETUP_MS = 34; // TCP + TLS + auth + backend fork
const QUERY_MS = 1;
const N = 1000;
const POOL = 10;

// No pool: every request pays setup + query
const noPoolTotal = N * (SETUP_MS + QUERY_MS);
const noPoolSetupPerReq = SETUP_MS;

// Pool: setup paid once per connection at fill, then only query per request
const poolFill = POOL * SETUP_MS;
const poolTotal = poolFill + N * QUERY_MS;
const poolSetupPerReq = poolFill / N;

console.log('no-pool total=' + noPoolTotal + 'ms setup/req=' + noPoolSetupPerReq + 'ms');
console.log('pool total=' + poolTotal + 'ms setup/req=' + poolSetupPerReq + 'ms');
console.log('speedup=' + (noPoolTotal / poolTotal).toFixed(1) + 'x');
